376	    private Long insert(String table, Object id, String[] columns, Object... values) {
377	        String cols = String.join(", ", columns);
378	        String marks = String.join(", ", Collections.nCopies(columns.length, "?"));
379	        if (id != null) {
380	            Object[] args = new Object[values.length + 1];
381	            args[0] = id(id);
382	            System.arraycopy(values, 0, args, 1, values.length);
383	            jdbc.update("INSERT INTO " + table + " (id, " + cols + ") VALUES (?, " + marks + ")", args);
384	            return id(id);
385	        }
386	        jdbc.update("INSERT INTO " + table + " (" + cols + ") VALUES (" + marks + ")", values);
387	        return jdbc.queryForObject("SELECT MAX(id) FROM " + table, Long.class);
388	    }
389	
390	    /** A whole number of days, not negative; null when left out. */
391	    private static Integer days(Object value, String field) {
392	        if (value == null) {
393	            return null;
394	        }
395	        try {
396	            int days = new BigDecimal(value.toString()).intValueExact();
397	            if (days < 0) {
398	                throw refuse(field + " cannot be negative, not " + value);
399	            }
400	            return days;
401	        } catch (NumberFormatException | ArithmeticException e) {
402	            throw refuse(field + " must be a whole number of days, not " + value);
403	        }
404	    }
405	
406	    /** A whole number of instalments from 2 to 24; null (no plan) when left out. */
407	    private static Integer instalments(Object value, String field) {
408	        if (value == null) {
409	            return null;
410	        }
411	        try {
412	            int count = new BigDecimal(value.toString()).intValueExact();
413	            if (count < Invoice.MIN_INSTALMENTS || count > Invoice.MAX_INSTALMENTS) {
414	                throw refuse(field + " must be from " + Invoice.MIN_INSTALMENTS + " to " + Invoice.MAX_INSTALMENTS
415	                        + ", not " + value);
416	            }
417	            return count;
418	        } catch (NumberFormatException | ArithmeticException e) {
419	            throw refuse(field + " must be a whole number, not " + value);
420	        }
421	    }
422	
423	    /** An annual interest rate from 0 to 30 with at most two decimals; none given is zero. */
424	    private static BigDecimal instalmentRate(Object value, String field) {
425	        BigDecimal rate = percent(value, field);
426	        if (rate.compareTo(Invoice.MAX_INSTALMENT_RATE) > 0) {
427	            throw refuse(field + " must be from 0 to " + Invoice.MAX_INSTALMENT_RATE + ", not " + value);
428	        }
429	        return rate;
430	    }
431	
432	    /** A true/false flag; false when left out. */
433	    private static boolean flag(Object value, String where) {
434	        if (value == null) {
435	            return false;
436	        }
437	        if (!(value instanceof Boolean b)) {
438	            throw refuse(where + " must be true or false");
439	        }
440	        return b;
441	    }
442	
443	    private static void only(Map<String, Object> row, Set<String> fields, String where) {
444	        for (String field : row.keySet()) {
445	            if (!fields.contains(field)) {
446	                throw refuse("unsupported field: " + where + "." + field);
447	            }
448	        }
449	    }
450	
451	    private static Long id(Object value) {
452	        if (value instanceof Number n) {
453	            return n.longValue();
454	        }
455	        try {
456	            return Long.valueOf(value.toString());
457	        } catch (NumberFormatException e) {
458	            throw refuse("not an id: " + value);
459	        }
460	    }
461	
462	    private static LocalDate date(Object value, String field) {
463	        try {
464	            return LocalDate.parse(value.toString());
465	        } catch (DateTimeParseException e) {
466	            throw refuse(field + " must be a yyyy-mm-dd date, not " + value);
467	        }
468	    }
469	
470	    /** A number stored to the cent; refuses a value it could only store by rounding. */
471	    private static BigDecimal cents(Object value, String field) {
472	        if (value == null) {
473	            throw refuse(field + " is required");
474	        }
475	        BigDecimal number;
476	        try {
477	            number = new BigDecimal(value.toString());
478	        } catch (NumberFormatException e) {
479	            throw refuse(field + " must be a number, not " + value);
480	        }
481	        if (number.stripTrailingZeros().scale() > 2) {
482	            throw refuse(field + " can have at most two decimals, not " + value);
483	        }
484	        return number;
485	    }
486	
487	    /** A percentage from 0 to 100 with at most two decimals; none given is zero. */
488	    private static BigDecimal percent(Object value, String field) {
489	        if (value == null) {
490	            return BigDecimal.ZERO;
491	        }
492	        BigDecimal number = cents(value, field);
493	        if (number.signum() < 0 || number.compareTo(BigDecimal.valueOf(100)) > 0) {
494	            throw refuse(field + " must be from 0 to 100, not " + value);
495	        }
496	        return number;
497	    }
498	
499	    /** An optional amount of money, not negative and to the cent; 0 when left out. */
500	    private static BigDecimal money(Object value, String field) {
501	        if (value == null) {
502	            return BigDecimal.ZERO;
503	        }
504	        BigDecimal number = cents(value, field);
505	        if (number.signum() < 0) {
506	            throw refuse(field + " cannot be negative, not " + value);
507	        }
508	        return number;
509	    }
510	
511	    @SuppressWarnings("unchecked")
512	    private static List<Map<String, Object>> rows(Object value, String key) {
513	        if (value == null) {
514	            return List.of();
515	        }
516	        if (!(value instanceof List<?> list)) {
517	            throw refuse(key + " must be a list of rows");
518	        }
519	        List<Map<String, Object>> out = new ArrayList<>();
520	        for (Object o : list) {
521	            if (!(o instanceof Map<?, ?> m)) {
522	                throw refuse(key + " must be a list of rows");
523	            }
524	            out.add((Map<String, Object>) m);
525	        }
526	        return out;
527	    }
528	
529	    private static String text(Map<String, Object> row, String field) {
530	        Object v = row.get(field);
531	        return v == null ? "" : v.toString();
532	    }
533	
534	    private static ResponseStatusException refuse(String message) {
535	        return new ResponseStatusException(HttpStatus.BAD_REQUEST, message);
536	    }
537	}
