209	    /**
210	     * How many decimals its amounts have: 2, to the cent, or 0 for whole yen. Wherever an amount is
211	     * rounded to the cent it is rounded to this instead.
212	     */
213	    public int scale() {
214	        return currency().scale();
215	    }
