394	     * the tax rate: first what it still owes, then the retention it holds back. The part taken off in
395	     * all, and of that the part clearing retention; the rest is left over as credit.
396	     */
397	    public BigDecimal[] creditTaken(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
398	        BigDecimal toDue = amount.min(amountDue(paid, taxRate).max(BigDecimal.ZERO));
399	        BigDecimal toRetention = amount.subtract(toDue).min(retentionHeld(taxRate));
