482	    /**
483	     * The plan's schedule at the tax rate, an ordinary loan of the grand total; empty when there is no
484	     * plan. With the monthly rate i (the annual rate / 12 / 100) the instalment is P x i / (1 - (1 +
485	     * i)^-n), or P / n at 0%, rounded half up to the cent. Each month's interest is the balance still
486	     * owed x i, rounded half up to the cent, and its principal the instalment less the interest; the
487	     * last instalment pays off the whole balance left plus its interest, so the schedule ends at zero.
488	     * Instalment k falls due k months after the issue date, on the same day (the month's last day when
489	     * it is shorter).
490	     */
491	    public List<Instalment> schedule(BigDecimal taxRate) {
492	        if (!hasPlan()) {
493	            return List.of();
494	        }
495	        MathContext mc = MathContext.DECIMAL128;
496	        BigDecimal principal = total(taxRate);
497	        BigDecimal i = instalmentRate.divide(BigDecimal.valueOf(1200), mc);
498	        int n = instalments;
499	        BigDecimal payment;
500	        if (i.signum() == 0) {
501	            payment = principal.divide(BigDecimal.valueOf(n), scale(), RoundingMode.HALF_UP);
502	        } else {
503	            BigDecimal growth = BigDecimal.ONE.add(i).pow(n, mc);
504	            payment = principal.multiply(i).multiply(growth)
505	                    .divide(growth.subtract(BigDecimal.ONE), mc).setScale(scale(), RoundingMode.HALF_UP);
506	        }
507	        List<Instalment> schedule = new ArrayList<>(n);
508	        BigDecimal balance = principal.setScale(scale(), RoundingMode.HALF_UP);
509	        for (int k = 1; k <= n; k++) {
510	            BigDecimal interest = balance.multiply(i).setScale(scale(), RoundingMode.HALF_UP);
511	            BigDecimal paid = k == n ? balance.add(interest) : payment;
512	            BigDecimal repaid = paid.subtract(interest);
513	            balance = balance.subtract(repaid);
514	            LocalDate due = issueDate == null ? null : issueDate.plusMonths(k);
515	            schedule.add(new Instalment(k, due, paid, interest, repaid, balance));
516	        }
517	        return schedule;
518	    }
