520	    /** The plan total at the tax rate: the sum of the instalments; null when there is no plan. */
521	    public BigDecimal planTotal(BigDecimal taxRate) {
522	        if (!hasPlan()) {
523	            return null;
524	        }
525	        return schedule(taxRate).stream().map(Instalment::payment).reduce(zero(), BigDecimal::add);
526	    }
527	
528	    /**
529	     * Each instalment of the plan at the tax rate once the given amount has been paid, on the given
530	     * day: payments (with what credit notes took off and anything written off) pay the instalments in
531	     * order, each paid off before the next. An instalment not paid off more than {@link #GRACE_DAYS}
532	     * days after its due date is overdue; empty when there is no plan.
533	     */
534	    public List<Instalment.Progress> instalmentProgress(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
535	        List<Instalment.Progress> progress = new ArrayList<>();
536	        BigDecimal left = paid.add(getCredited()).add(writtenOff(paid, taxRate));
537	        for (Instalment instalment : schedule(taxRate)) {
538	            BigDecimal part = left.min(instalment.payment()).max(BigDecimal.ZERO).setScale(scale(), RoundingMode.HALF_UP);
539	            left = left.subtract(part);
540	            BigDecimal unpaid = instalment.payment().subtract(part);
541	            Instalment.Status status;
542	            if (unpaid.signum() <= 0) {
543	                status = Instalment.Status.PAID;
544	            } else if (instalment.dueDate() != null && today.isAfter(instalment.dueDate().plusDays(GRACE_DAYS))) {
545	                status = Instalment.Status.OVERDUE;
546	            } else if (part.signum() > 0) {
547	                status = Instalment.Status.PART_PAID;
548	            } else {
549	                status = Instalment.Status.DUE;
550	            }
551	            progress.add(new Instalment.Progress(instalment, part, unpaid, status));
552	        }
553	        return progress;
554	    }
