556	    /**
557	     * What is overdue at the tax rate once the given amount has been paid, on the given day: for a plan,
558	     * only what is unpaid on its overdue instalments; otherwise all that is due when it is overdue.
559	     */
560	    public BigDecimal overdueAmount(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
561	        if (statusWhenPaid(paid, taxRate, today) != InvoiceStatus.OVERDUE) {
562	            return zero();
563	        }
564	        if (!hasPlan()) {
565	            return amountDue(paid, taxRate);
566	        }
567	        return instalmentProgress(paid, taxRate, today).stream()
568	                .filter(p -> p.status() == Instalment.Status.OVERDUE).map(Instalment.Progress::unpaid)
569	                .reduce(zero(), BigDecimal::add);
570	    }
