658	    /** Days past its due date an invoice is given before it becomes overdue: a week's grace. */
659	    public static final int GRACE_DAYS = 7;
660	
661	    /**
662	     * The status on the given day once the given amount has been paid against the grand total at the
663	     * tax rate: a sent invoice with something still due more than {@link #GRACE_DAYS} days after its
664	     * due date is overdue, part paid or not. Held retention is never due, so never makes it overdue;
665	     * released retention is due {@link #RETENTION_DUE_DAYS} days after its release, and payments go to
666	     * the rest of the invoice before it. An invoice spread over instalments is instead overdue when any
667	     * of its instalments is (see {@link #instalmentProgress}).
668	     */
669	    public InvoiceStatus statusWhenPaid(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
670	        return statusWhenPaid(paid, null, taxRate, today);
671	    }
672	
673	    /**
674	     * As {@link #statusWhenPaid(BigDecimal, BigDecimal, LocalDate)}, but a fully paid invoice whose
675	     * paid date (null when not known) is after its due date is paid late.
676	     */
677	    public InvoiceStatus statusWhenPaid(BigDecimal paid, LocalDate paidOn, BigDecimal taxRate, LocalDate today) {
678	        if (status != InvoiceStatus.SENT) {
679	            return status;
680	        }
681	        BigDecimal amountDue = amountDue(paid, taxRate);
682	        boolean due = amountDue.signum() > 0;
683	        BigDecimal retentionDue = amountDue.min(retentionReleased(taxRate)).max(BigDecimal.ZERO);
684	        boolean restDue = amountDue.subtract(retentionDue).signum() > 0;
685	        if (hasPlan()) {
686	            if (due && instalmentProgress(paid, taxRate, today).stream()
687	                    .anyMatch(p -> p.status() == Instalment.Status.OVERDUE)) {
688	                return InvoiceStatus.OVERDUE;
689	            }
690	        } else if (restDue && dueDate != null && today.isAfter(dueDate.plusDays(GRACE_DAYS))) {
691	            return InvoiceStatus.OVERDUE;
692	        }
693	        if (retentionDue.signum() > 0 && today.isAfter(retentionDueDate().plusDays(GRACE_DAYS))) {
694	            return InvoiceStatus.OVERDUE;
695	        }
696	        if (!due && retentionHeld(taxRate).signum() > 0) {
697	            return InvoiceStatus.RETENTION_HELD;
698	        }
699	        if (paid.signum() <= 0) {
700	            return !due && getCredited().signum() > 0 ? InvoiceStatus.CREDITED : status;
701	        }
702	        if (due) {
703	            return InvoiceStatus.PART_PAID;
704	        }
705	        return paidOn != null && dueDate != null && paidOn.isAfter(dueDate) ? InvoiceStatus.PAID_LATE
706	                : InvoiceStatus.PAID;
707	    }
708	
709	    /**
710	     * The date the invoice was fully paid: the date of the payment that cleared its grand total at the
711	     * tax rate, taking the parts of payments (not reversed) in the order they were applied (credit used
712	     * counts on the day it was applied); null while something is still due or retention is held.
713	     */
714	    public LocalDate paidOn(List<Payment> payments, BigDecimal taxRate) {
715	        BigDecimal total = payable(taxRate);
716	        if (status != InvoiceStatus.SENT || total.signum() <= 0 || retentionHeld(taxRate).signum() > 0) {
717	            return null;
718	        }
719	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
720	        }
721	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
722	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
723	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
724	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
725	        BigDecimal sum = BigDecimal.ZERO;
726	        for (Part p : inOrder) {
727	            sum = sum.add(p.amount());
728	            if (sum.signum() > 0 && isSmallEnoughToWriteOff(total.subtract(sum))) {
729	                return p.on();
730	            }
731	        }
732	        return null;
733	    }
734	
735	    /**
736	     * What is still due once the given amount has been paid: the grand total less it, less what credit
737	     * notes have credited, less the retention still held, less anything written off — so nothing once
738	     * payments leave less than {@link #WRITE_OFF_LIMIT}. A credit note itself has nothing due.
739	     */
740	    public BigDecimal amountDue(BigDecimal paid, BigDecimal taxRate) {
741	        if (isCreditNote()) {
742	            return zero();
743	        }
744	        return payable(taxRate).subtract(paid).subtract(writtenOff(paid, taxRate));
745	    }
746	
747	    /**
748	     * What is written off once the given amount has been paid: when payments leave less than
749	     * {@link #WRITE_OFF_LIMIT} still due, all of what is left; otherwise nothing.
750	     */
751	    public BigDecimal writtenOff(BigDecimal paid, BigDecimal taxRate) {
752	        BigDecimal left = payable(taxRate).subtract(paid);
753	        return !isCreditNote() && paid.signum() > 0 && left.signum() > 0 && isSmallEnoughToWriteOff(left)
754	                ? left.setScale(scale(), RoundingMode.HALF_UP)
755	                : zero();
756	    }
757	
758	    /** The least a part payment may be at the tax rate: {@link #MINIMUM_PART_SHARE} of the grand total. */
759	    public BigDecimal minimumPart(BigDecimal taxRate) {
760	        return total(taxRate).multiply(MINIMUM_PART_SHARE).setScale(scale(), RoundingMode.HALF_UP);
761	    }
762	
763	    /**
764	     * Whether paying the amount on top of what was already paid is too small a part payment: under
765	     * {@link #minimumPart} while leaving something still due (what would be written off counts as settled).
766	     * For a plan the least is instead what is still unpaid on its earliest unpaid instalment.
767	     */
768	    public boolean isTooSmallPart(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
769	        if (hasPlan()) {
770	            return amount.compareTo(earliestUnpaid(paid, taxRate)) < 0
771	                    && amountDue(paid.add(amount), taxRate).signum() > 0;
772	        }
773	        return amount.compareTo(minimumPart(taxRate)) < 0 && amountDue(paid.add(amount), taxRate).signum() > 0;
774	    }
775	
776	    /** Adds a line to the end of the invoice. */
777	    public void addLine(InvoiceLine line) {
778	        lines.add(line);
779	    }
780	
781	    /** Whether the invoice has the line with the given id. */
782	    public boolean hasLine(Long lineId) {
783	        return lines.stream().anyMatch(l -> lineId.equals(l.getId()));
784	    }
785	
786	    /**
787	     * Removes the line with the given id; whether the invoice had it. Refused when what is left would
788	     * be less than a fixed discount on the invoice.
789	     */
790	    public boolean removeLine(Long lineId) {
791	        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
792	        if (line == null) {
793	            return false;
794	        }
795	        BigDecimal left = subtotal().subtract(line.amount(scale()));
796	        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
797	            throw new InvoiceRejectedException("This line cannot be removed: the "
798	                    + currency().format(left) + " left would be less than the "
799	                    + currency().format(discountAmount) + " discount.");
800	        }
801	        lines.remove(line);
802	        return true;
803	    }
804	
805	    /**
806	     * Changes the line with the given id to the given values; whether the invoice had it. Refused when
807	     * the subtotal would then be less than a fixed discount on the invoice.
808	     */
809	    public boolean updateLine(Long lineId, String description, BigDecimal qty, BigDecimal unitPrice,
810	            boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
811	        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
812	        if (line == null) {
813	            return false;
814	        }
815	        BigDecimal changed = new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate).amount(scale());
816	        BigDecimal left = subtotal().subtract(line.amount(scale())).add(changed);
817	        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
818	            throw new InvoiceRejectedException("This line cannot be changed: the "
819	                    + currency().format(left) + " subtotal would be less than the "
820	                    + currency().format(discountAmount) + " discount.");
821	        }
822	        line.update(description, qty, unitPrice, taxExempt, discountPct, taxRate);
823	        return true;
824	    }
825	
826	    /**
827	     * The sum of the line amounts, each after its own discount and already to the cent — so the subtotal
828	     * matches what a client gets by adding up the lines shown.
829	     */
830	    public BigDecimal subtotal() {
831	        return lines.stream().map(l -> l.amount(scale()))
832	                .reduce(zero(), BigDecimal::add);
833	    }
834	
835	    /**
836	     * The amount taken off: the fixed amount when there is one (never more than the subtotal, should
837	     * lines have been changed since), otherwise the discount percentage of the subtotal, rounded down
838	     * to the cent. When there is a cap, it limits everything taken off — the line discounts plus
839	     * this — so this shrinks to what the line discounts leave under the cap, never below zero.
840	     */
841	    public BigDecimal discount() {
842	        BigDecimal discount = discountAmount.signum() > 0
843	                ? discountAmount.min(subtotal()).setScale(scale(), RoundingMode.HALF_UP)
844	                : subtotal().multiply(discountPct).divide(BigDecimal.valueOf(100)).setScale(scale(), RoundingMode.DOWN);
845	        if (discountCap == null) {
846	            return discount;
847	        }
848	        BigDecimal lineDiscounts = lines.stream().map(l -> l.discount(scale()))
849	                .reduce(zero(), BigDecimal::add);
850	        BigDecimal left = discountCap.setScale(scale(), RoundingMode.HALF_UP).subtract(lineDiscounts).max(zero());
851	        return discount.min(left);
852	    }
853	
854	    /**
855	     * Each line's share of the discount, in the order of the lines. The discount's cents are split in
856	     * proportion to the line amounts: each line first gets the whole cents of its exact share
857	     * (rounded down), then the cents left over go one each to the lines with the largest leftover
858	     * fractions; between equal fractions the cent goes to the line with the larger amount, and between
859	     * equal amounts too to the lower line id. The shares add up to the discount.
860	     */
861	    public List<BigDecimal> discountShares() {
862	        BigInteger discountCents = discount().movePointRight(scale()).toBigIntegerExact();
863	        BigInteger subtotalCents = subtotal().movePointRight(scale()).toBigIntegerExact();
864	        int n = lines.size();
865	        BigInteger[] shares = new BigInteger[n];
866	        BigInteger[] leftovers = new BigInteger[n];
867	        BigInteger given = BigInteger.ZERO;
868	        for (int i = 0; i < n; i++) {
869	            if (subtotalCents.signum() == 0) {
870	                shares[i] = BigInteger.ZERO;
871	                leftovers[i] = BigInteger.ZERO;
872	            } else {
873	                // The exact share is discount * amount / subtotal; all fractions share the subtotal
874	                // as denominator, so the remainders compare as the fractions do.
875	                BigInteger[] qr = discountCents.multiply(lines.get(i).amount(scale()).movePointRight(scale()).toBigIntegerExact())
876	                        .divideAndRemainder(subtotalCents);
877	                shares[i] = qr[0];
878	                leftovers[i] = qr[1];
879	            }
880	            given = given.add(shares[i]);
881	        }
882	        List<Integer> order = new ArrayList<>();
883	        for (int i = 0; i < n; i++) {
884	            order.add(i);
885	        }
886	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
887	                .thenComparing(Comparator.<Integer, BigDecimal>comparing(i -> lines.get(i).amount(scale())).reversed())
888	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
889	        int left = discountCents.subtract(given).intValueExact();
890	        for (int k = 0; k < left; k++) {
891	            int i = order.get(k);
892	            shares[i] = shares[i].add(BigInteger.ONE);
893	        }
894	        List<BigDecimal> result = new ArrayList<>(n);
895	        for (BigInteger share : shares) {
896	            result.add(new BigDecimal(share, scale()));
897	        }
898	        return result;
899	    }
900	
901	    /**
902	     * Each line's tax, in the order of the lines: the line's own rate (a percentage), or the given
903	     * workspace rate when it has none, on the line's amount less its share of the discount, rounded
904	     * half up to the cent. Tax-exempt lines, and every line of a tax-exempt client, have no tax.
905	     */
906	    public List<BigDecimal> lineTaxes(BigDecimal taxRate) {
907	        List<BigDecimal> shares = discountShares();
908	        List<BigDecimal> taxes = new ArrayList<>(lines.size());
909	        for (int i = 0; i < lines.size(); i++) {
910	            InvoiceLine line = lines.get(i);
911	            taxes.add(clientTaxExempt || line.isTaxExempt() ? zero()
912	                    : line.amount(scale()).subtract(shares.get(i)).multiply(line.taxRate(taxRate)).divide(BigDecimal.valueOf(100))
913	                            .setScale(scale(), RoundingMode.HALF_UP));
914	        }
915	        return taxes;
916	    }
917	
918	    /** The tax charged at the given rate (a percentage): the sum of the line taxes. */
919	    public BigDecimal tax(BigDecimal taxRate) {
920	        return lineTaxes(taxRate).stream().reduce(zero(), BigDecimal::add);
921	    }
922	
923	    /** The grand total: the subtotal less the discount, plus tax at the given rate. */
924	    public BigDecimal total(BigDecimal taxRate) {
925	        return subtotal().subtract(discount()).add(tax(taxRate));
926	    }
927	}
