83	    /**
84	     * A new draft for the invoice's client with copies of its lines and the same invoice discount,
85	     * issued today and due as any new invoice is, and records it in the audit; empty if no such
86	     * invoice. Payments are not copied.
87	     */
88	    @Transactional
89	    public Optional<Invoice> duplicate(Long invoiceId) {
90	        return invoices.findWithLinesById(invoiceId).map(original -> {
91	            if (original.isCreditNote()) {
92	                throw new InvoiceRejectedException("A credit note cannot be duplicated.");
93	            }
94	            LocalDate issued = today.date();
95	            Invoice copy = invoices.saveAndFlush(original.duplicate(issued, dueDateFor(original.getClientId(), issued)));
96	            audit.record("INVOICE_DUPLICATED from=" + InvoiceNumber.of(original.getId())
97	                    + " to=" + InvoiceNumber.of(copy.getId()));
