102	    /**
103	     * A new, empty draft credit note against the sent invoice, issued today; empty if no such invoice.
104	     * A draft, a void invoice or a credit note is refused.
105	     */
106	    @Transactional
107	    public Optional<Invoice> creditNote(Long invoiceId) {
108	        return invoices.findWithLinesById(invoiceId).map(original -> {
109	            if (original.isCreditNote()) {
110	                throw new InvoiceRejectedException("A credit note cannot itself be credited.");
111	            }
112	            if (original.isDraft()) {
113	                throw new InvoiceRejectedException("Only a sent invoice can be credited.");
114	            }
115	            if (original.isVoid()) {
116	                throw new InvoiceRejectedException("A void invoice cannot be credited.");
117	            }
118	            return invoices.saveAndFlush(original.creditNote(today.date()));
119	        });
120	    }
