139	    /**
140	     * Adds a line to an invoice; empty if no such invoice. The line has already been checked. A sent
141	     * invoice with no payments goes back to draft; one with a payment refuses it.
142	     */
143	    @Transactional
144	    public Optional<Invoice> addLine(Long invoiceId, String description, BigDecimal qty, BigDecimal unitPrice,
145	            boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
146	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
147	        found.ifPresent(invoice -> {
148	            requireWhole(invoice.currency(), unitPrice, "The unit price");
149	            boolean reopened = reopenForChange(invoice, "A paid invoice cannot take new lines.");
150	            invoice.addLine(new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate));
151	            invoices.saveAndFlush(invoice);
