209	    /**
210	     * Gives an invoice a percentage discount, or a fixed amount off when one is given; the one given
211	     * clears the other, and the cap (null for none) limits everything taken off, line discounts included. Empty if no such invoice. The values have already been checked; a fixed amount
212	     * over the subtotal is refused, as is a discount taking off more than a fifth of the subtotal
213	     * (after the cap) without a reason. A sent invoice with no payments goes back to draft; one with a
214	     * payment refuses it.
215	     */
216	    @Transactional
217	    public Optional<Invoice> setDiscount(Long invoiceId, BigDecimal discountPct, BigDecimal discountAmount,
218	            BigDecimal discountCap, String discountReason) {
219	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
220	        found.ifPresent(invoice -> {
221	            if (invoice.isCreditNote()) {
222	                throw new InvoiceRejectedException("A credit note has no discount.");
223	            }
224	            if (discountAmount != null) {
225	                requireWhole(invoice.currency(), discountAmount, "The discount amount");
226	            }
227	            if (discountCap != null) {
228	                requireWhole(invoice.currency(), discountCap, "The discount cap");
229	            }
230	            boolean reopened = reopenForChange(invoice, "A paid invoice cannot be given a discount.");
231	            if (discountAmount != null) {
232	                invoice.setDiscountAmount(discountAmount);
233	            } else {
234	                invoice.setDiscountPct(discountPct);
235	            }
236	            invoice.setDiscountCap(discountCap);
237	            invoice.setDiscountReason(discountReason);
238	            if (invoice.discountLacksReason()) {
239	                throw new InvoiceRejectedException(
240	                        "A discount of more than 20% of the subtotal needs a reason.");
241	            }
242	            invoices.saveAndFlush(invoice);
243	            if (reopened) {
244	                audit.record("INVOICE_REOPENED id=" + invoice.getId());
245	            }
246	        });
247	        return found;
248	    }
