268	    /**
269	     * Sets the percentage of a draft's amount before tax held back as retention; empty if no such invoice.
270	     * The percentage has already been checked; any invoice that is not a draft, or a credit note, is refused.
271	     */
272	    @Transactional
273	    public Optional<Invoice> setRetention(Long invoiceId, BigDecimal retentionPct) {
274	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
275	        found.ifPresent(invoice -> {
276	            if (invoice.isCreditNote()) {
277	                throw new InvoiceRejectedException("A credit note holds back no retention.");
278	            }
279	            if (!invoice.isDraft()) {
280	                throw new InvoiceRejectedException("Retention can only be set on a draft.");
281	            }
282	            if (invoice.hasPlan() && retentionPct.signum() > 0) {
283	                throw new InvoiceRejectedException("An invoice spread over instalments cannot also hold back retention.");
284	            }
285	            invoice.setRetentionPct(retentionPct);
286	            invoices.saveAndFlush(invoice);
287	        });
288	        return found;
