291	    /**
292	     * Spreads a draft over the number of monthly instalments at the annual interest rate; empty if no
293	     * such invoice. Both have already been checked; any invoice that is not a draft, a credit note, or
294	     * one holding back retention is refused.
295	     */
296	    @Transactional
297	    public Optional<Invoice> setPlan(Long invoiceId, int instalments, BigDecimal instalmentRate) {
298	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
299	        found.ifPresent(invoice -> {
300	            if (invoice.isCreditNote()) {
301	                throw new InvoiceRejectedException("A credit note cannot be spread over instalments.");
302	            }
303	            if (!invoice.isDraft()) {
304	                throw new InvoiceRejectedException("Only a draft can be spread over instalments.");
305	            }
306	            if (invoice.getRetentionPct().signum() > 0) {
307	                throw new InvoiceRejectedException("An invoice holding back retention cannot also be spread over instalments.");
308	            }
309	            invoice.setPlan(instalments, instalmentRate);
310	            invoices.saveAndFlush(invoice);
311	        });
312	        return found;
313	    }
