344	    /**
345	     * Readies the invoice for a change: a draft stays as it is; a sent invoice with no payments goes
346	     * back to draft, to be sent again; an invoice with any payment is refused with the message.
347	     * Whether it went back to draft.
348	     */
349	    private boolean reopenForChange(Invoice invoice, String refusal) {
350	        if (invoice.isDraft()) {
351	            return false;
352	        }
353	        if (invoice.isVoid()) {
354	            throw new InvoiceRejectedException("A void invoice cannot be changed.");
355	        }
356	        if (invoice.isCreditNote()) {
357	            throw new InvoiceRejectedException("An issued credit note cannot be changed.");
358	        }
359	        if (invoice.hasCreditNotesIssued()) {
360	            throw new InvoiceRejectedException("An invoice with an issued credit note cannot be changed.");
361	        }
362	        if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
363	            throw new InvoiceRejectedException(refusal);
364	        }
365	        invoice.reopen();
366	        return true;
367	    }
