597	    /**
598	     * Voids a sent invoice with no payments, and records it in the audit; empty if no such invoice. A
599	     * draft, an invoice already void, or one with any payment is refused.
600	     */
601	    @Transactional
602	    public Optional<Invoice> voidInvoice(Long invoiceId) {
603	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
604	        found.ifPresent(invoice -> {
605	            if (invoice.isVoid()) {
606	                throw new InvoiceRejectedException("This invoice is already void.");
607	            }
608	            if (invoice.isDraft()) {
609	                throw new InvoiceRejectedException("A draft cannot be voided; only a sent invoice can.");
610	            }
611	            if (invoice.isCreditNote()) {
612	                throw new InvoiceRejectedException("An issued credit note cannot be voided.");
613	            }
614	            if (invoice.hasCreditNotesIssued()) {
615	                throw new InvoiceRejectedException("An invoice with an issued credit note cannot be voided.");
616	            }
617	            if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
618	                throw new InvoiceRejectedException("An invoice with payments cannot be voided.");
619	            }
620	            invoice.markVoid();
621	            invoices.saveAndFlush(invoice);
622	            audit.record("INVOICE_VOIDED id=" + invoice.getId() + " number=" + invoice.number());
623	        });
624	        return found;
625	    }
