633	    /** The date each fully paid invoice was paid (see {@link Invoice#paidOn}); an invoice not fully paid is left out. */
634	    @Transactional(readOnly = true)
635	    public Map<Long, LocalDate> paidOn(List<Invoice> list) {
636	        Map<Long, LocalDate> paidOn = new HashMap<>();
637	        if (list.isEmpty()) {
638	            return paidOn;
639	        }
640	        List<Payment> found = payments.findForInvoices(list.stream().map(Invoice::getId).toList());
641	        BigDecimal rate = taxRate.percent();
642	        for (Invoice i : list) {
643	            LocalDate on = i.paidOn(found, rate);
644	            if (on != null) {
645	                paidOn.put(i.getId(), on);
646	            }
647	        }
