650	
651	    /** What has been paid to each of the invoices; an invoice paid nothing is paid zero. */
652	    @Transactional(readOnly = true)
653	    public Map<Long, BigDecimal> paid(List<Invoice> list) {
654	        Map<Long, BigDecimal> paid = new HashMap<>();
655	        list.forEach(i -> paid.put(i.getId(), BigDecimal.ZERO.setScale(2)));
656	        if (!list.isEmpty()) {
657	            for (Object[] row : payments.paidTo(list.stream().map(Invoice::getId).toList())) {
658	                paid.put((Long) row[0], ((BigDecimal) row[1]).setScale(2));
659	            }
660	        }
661	        return paid;
662	    }
663	
664	    /**
665	     * Records a payment of the amount on the date against a sent invoice that still has something
666	     * due, and records it in the audit; empty if no such invoice. The amount has already been
667	     * checked; what it pays beyond what is due is held on the client's account as credit. A draft, an
668	     * invoice already paid, or a date after today
669	     * or before the invoice's issue date is refused. The reference (null when none was quoted) has
670	     * already been checked; one that belongs to a different invoice is refused.
671	     */
672	    @Transactional
673	    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal paidAmount, Currency paidIn, LocalDate date,
674	            String reference) {
675	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
676	        found.ifPresent(invoice -> {
677	            if (invoice.isDraft()) {
678	                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
679	            }
680	            if (invoice.isVoid()) {
681	                throw new InvoiceRejectedException("A void invoice takes no payments.");
682	            }
683	            if (invoice.isCreditNote()) {
684	                throw new InvoiceRejectedException("A credit note takes no payments.");
685	            }
686	            BigDecimal amount = converted(paidAmount, paidIn, invoice.currency());
687	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
688	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
689	            if (due.signum() <= 0) {
690	                throw new InvoiceRejectedException("This invoice has already been paid.");
691	            }
692	            LocalDate now = today.date();
693	            BigDecimal early = BigDecimal.ZERO;
694	            BigDecimal settle = date.isAfter(now) ? null : invoice.settleAmount(paidSoFar, taxRate.percent(), date);
695	            if (settle != null && amount.compareTo(settle) >= 0) {
696	                early = invoice.earlyDiscount(taxRate.percent());
697	                invoice.takeEarlyDiscount(early);
698	                due = settle;
699	            }
700	            BigDecimal applied = amount.min(due);
701	            if (invoice.hasPlan() && invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
702	                throw new InvoiceRejectedException("A payment must be at least the "
703	                        + invoice.currency().format(invoice.earliestUnpaid(paidSoFar, taxRate.percent()))
704	                        + " still unpaid on the earliest unpaid instalment, unless it settles the plan.");
705	            }
706	            if (invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
707	                throw new InvoiceRejectedException("A part payment must be at least "
708	                        + invoice.currency().format(invoice.minimumPart(taxRate.percent()))
709	                        + " (10% of the total), unless it settles the invoice.");
710	            }
711	            if (date.isAfter(now)) {
712	                throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
713	            }
714	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
715	                throw new InvoiceRejectedException(
716	                        "The payment date cannot be before the invoice's issue date (" + invoice.getIssueDate() + ").");
717	            }
718	            if (reference != null && !reference.equals(PaymentReference.of(invoice.getId()))) {
719	                throw new InvoiceRejectedException(PaymentReference.grouped(reference)
720	                        + " is the reference of a different invoice; this invoice's is "
721	                        + PaymentReference.grouped(PaymentReference.of(invoice.getId())) + ".");
722	            }
723	            Payment payment = payments.saveAndFlush(Payment.against(invoice, amount, applied, date, reference)
724	                    .paidIn(paidIn, paidAmount, invoice.currency()));
725	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
726	                    + applied.setScale(invoice.scale(), RoundingMode.UNNECESSARY).toPlainString());
727	            if (early.signum() > 0) {
728	                invoices.saveAndFlush(invoice);
729	                audit.record("EARLY_DISCOUNT id=" + invoice.getId() + " amount=" + early.toPlainString());
730	            }
731	            recordWriteOff(invoice);
732	            recordCreditHeld(payment);
733	        });
734	        return found;
735	    }
736	
737	    /**
738	     * Records one payment of the amount on the date against the client's unpaid sent invoices, earliest
739	     * due date first (lower id first on the same due date) so overdue invoices are cleared first,
740	     * paying each off in full before the next.
741	     * What it pays beyond everything the client owes is held on the client's account as credit; the
742	     * rest is checked and recorded as a split payment over the invoices it reaches.
743	     * References (empty when none, each already checked) instead limit the payment to the client's
744	     * invoices with those references, applied in the same order; one that is not the reference of any
745	     * of the client's invoices is refused; what is paid beyond what those invoices owe together is held
746	     * as credit.
747	     * The payment keeps the reference of the first invoice it reaches.
748	     */
749	    @Transactional
750	    public Payment recordAutoPayment(Long clientId, BigDecimal paidAmount, Currency paidIn, LocalDate date,
751	            List<String> references) {
752	        BigDecimal amount = converted(paidAmount, paidIn, currencyOf(clientId));
753	        List<Invoice> ofClient = invoices.findByClientIdOrderByIdAsc(clientId);
754	        List<Invoice> candidates = ofClient;
755	        if (!references.isEmpty()) {
756	            Set<Long> named = new HashSet<>();
757	            for (String reference : references) {
758	                Invoice invoice = ofClient.stream()
759	                        .filter(i -> reference.equals(PaymentReference.of(i.getId())))
760	                        .findFirst()
761	                        .orElseThrow(() -> new InvoiceRejectedException(PaymentReference.grouped(reference)
762	                                + " is not the reference of any of this client's invoices."));
763	                String number = InvoiceNumber.of(invoice.getId());
764	                if (invoice.isDraft()) {
765	                    throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
766	                }
767	                if (invoice.isVoid()) {
768	                    throw new InvoiceRejectedException(number + " is void and takes no payments.");
769	                }
770	                if (invoice.isCreditNote()) {
771	                    throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
772	                }
773	                named.add(invoice.getId());
774	            }
775	            candidates = ofClient.stream().filter(i -> named.contains(i.getId())).toList();
776	        }
777	        List<Invoice> sent = candidates.stream()
778	                .filter(i -> !i.isDraft() && !i.isVoid() && !i.isCreditNote())
779	                .sorted(Comparator.comparing(Invoice::getDueDate, Comparator.nullsLast(Comparator.naturalOrder()))
780	                        .thenComparing(Invoice::getId))
781	                .toList();
782	        Map<Long, BigDecimal> paid = paid(sent);
783	        BigDecimal owed = BigDecimal.ZERO;
784	        BigDecimal left = amount;
785	        List<PaymentAllocation> parts = new ArrayList<>();
786	        for (Invoice invoice : sent) {
787	            BigDecimal due = invoice.amountDue(paid.get(invoice.getId()), taxRate.percent());
788	            if (due.signum() <= 0) {
789	                continue;
790	            }
791	            owed = owed.add(due);
792	            if (left.signum() > 0) {
793	                BigDecimal part = left.min(due);
794	                parts.add(new PaymentAllocation(invoice.getId(), part));
795	                left = left.subtract(part);
796	            }
797	        }
798	        if (owed.signum() <= 0) {
799	            throw new InvoiceRejectedException(references.isEmpty() ? "The client has no unpaid invoices to pay."
800	                    : "Those invoices have already been paid.");
801	        }
802	        String reference = references.isEmpty() ? null : PaymentReference.of(parts.get(0).getInvoiceId());
803	        return recordSpread(clientId, amount, paidAmount, paidIn, date, reference, parts, true);
804	    }
805	
806	    /**
807	     * Records one payment of the amount on the date spread over several of the client's invoices, and
808	     * records each part in the audit. The amounts have already been checked to be more than zero; they
809	     * must add up exactly to the payment, and each must go to a different sent invoice of the client
810	     * and be no more than what it still has due. The date must be no later than today nor before any
811	     * of the invoices' issue dates. The reference (null when none) has already been checked; it must
812	     * be the reference of one of the invoices.
813	     */
814	    @Transactional
815	    public Payment recordSplitPayment(Long clientId, BigDecimal paidAmount, Currency paidIn, LocalDate date,
816	            String reference, List<PaymentAllocation> parts) {
817	        BigDecimal amount = converted(paidAmount, paidIn, currencyOf(clientId));
818	        return recordSpread(clientId, amount, paidAmount, paidIn, date, reference, parts, false);
819	    }
820	
821	    /**
822	     * Records the payment spread over the parts as {@link #recordSplitPayment} does, except that when
823	     * credit may be held the parts may add up to less than the payment: the rest is held on the
824	     * client's account as credit and recorded in the audit.
825	     */
826	    private Payment recordSpread(Long clientId, BigDecimal amount, BigDecimal paidAmount, Currency paidIn,
827	            LocalDate date, String reference, List<PaymentAllocation> parts, boolean holdCredit) {
828	        if (parts.isEmpty()) {
829	            throw new InvoiceRejectedException("Enter how much of the payment goes to each invoice.");
830	        }
831	        Currency currency = currencyOf(clientId);
832	        requireWhole(currency, amount, "The amount");
833	        for (PaymentAllocation part : parts) {
834	            requireWhole(currency, part.getAmount(), "Each invoice's part");
835	        }
836	        BigDecimal sum = parts.stream().map(PaymentAllocation::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
837	        if (holdCredit ? sum.compareTo(amount) > 0 : sum.compareTo(amount) != 0) {
838	            throw new InvoiceRejectedException("The amounts for the invoices add up to "
839	                    + currency.format(sum) + ", not the " + currency.format(amount) + " paid.");
840	        }
841	        LocalDate now = today.date();
842	        if (date.isAfter(now)) {
843	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
844	        }
845	        Set<Long> seen = new HashSet<>();
846	        List<Invoice> spreadOver = new ArrayList<>();
847	        for (PaymentAllocation part : parts) {
848	            if (!seen.add(part.getInvoiceId())) {
849	                throw new InvoiceRejectedException("Each invoice can take only one part of the payment.");
850	            }
851	            Invoice invoice = invoices.findWithLinesById(part.getInvoiceId())
852	                    .filter(i -> i.getClientId().equals(clientId))
853	                    .orElseThrow(() -> new InvoiceRejectedException("A part of the payment goes to an invoice of another client."));
854	            String number = InvoiceNumber.of(invoice.getId());
855	            if (invoice.isDraft()) {
856	                throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
857	            }
858	            if (invoice.isVoid()) {
859	                throw new InvoiceRejectedException(number + " is void and takes no payments.");
860	            }
861	            if (invoice.isCreditNote()) {
862	                throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
863	            }
864	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
865	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
866	            if (part.getAmount().compareTo(due) > 0) {
867	                throw new InvoiceRejectedException("The " + currency.format(part.getAmount()) + " for "
868	                        + number + " is more than the " + currency.format(due) + " it has due.");
869	            }
870	            if (invoice.hasPlan() && invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
871	                throw new InvoiceRejectedException("The " + currency.format(part.getAmount()) + " for "
872	                        + number + " is less than the " + currency.format(invoice.earliestUnpaid(paidSoFar, taxRate.percent()))
873	                        + " still unpaid on its earliest unpaid instalment, unless it settles the plan.");
874	            }
875	            if (invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
876	                throw new InvoiceRejectedException("The " + currency.format(part.getAmount()) + " for "
877	                        + number + " is less than " + currency.format(invoice.minimumPart(taxRate.percent()))
878	                        + " (10% of its total), unless it settles the invoice.");
879	            }
880	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
881	                throw new InvoiceRejectedException("The payment date cannot be before the issue date of " + number
882	                        + " (" + invoice.getIssueDate() + ").");
883	            }
884	            spreadOver.add(invoice);
885	        }
886	        if (reference != null && spreadOver.stream().noneMatch(i -> reference.equals(PaymentReference.of(i.getId())))) {
887	            throw new InvoiceRejectedException(PaymentReference.grouped(reference)
888	                    + " is not the reference of any of the invoices being paid.");
889	        }
890	        Payment payment = payments.saveAndFlush(Payment.split(clientId, amount, date, reference, parts)
891	                .paidIn(paidIn, paidAmount, currency));
892	        for (PaymentAllocation part : parts) {
893	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + part.getInvoiceId() + " amount="
894	                    + part.getAmount().setScale(currency.scale(), RoundingMode.UNNECESSARY).toPlainString());
895	        }
896	        spreadOver.forEach(this::recordWriteOff);
897	        recordCreditHeld(payment);
898	        return payment;
899	    }
900	
901	    /**
902	     * The amount paid in the currency (null for the client's own) converted into the client's currency
903	     * through US dollars at the workspace rates; this is what is applied and checked. The amount must be
904	     * whole in the currency it was paid in, and must still be more than zero once converted.
905	     */
906	    private BigDecimal converted(BigDecimal paidAmount, Currency paidIn, Currency clientCurrency) {
907	        Currency from = paidIn == null ? clientCurrency : paidIn;
908	        requireWhole(from, paidAmount, "The amount");
909	        BigDecimal amount = exchangeRates.convert(paidAmount, from, clientCurrency);
910	        if (amount.signum() <= 0) {
911	            throw new InvoiceRejectedException("The amount is worth nothing once converted into "
912	                    + clientCurrency.name() + ".");
913	        }
914	        return amount;
915	    }
916	
917	    /** The currency the client is billed in; US dollars when there is no such client. */
918	    private Currency currencyOf(Long clientId) {
919	        return clients.findById(clientId).map(Client::getCurrency).orElse(Currency.USD);
920	    }
921	
922	    /**
923	     * Refuses an amount entered with more decimals than the currency has: whole yen for a yen client
924	     * (the cent is already checked for the rest).
925	     */
926	    private static void requireWhole(Currency currency, BigDecimal amount, String what) {
927	        if (amount != null && !currency.isWhole(amount)) {
928	            throw new InvoiceRejectedException(what + " must be in whole yen, with no decimals.");
929	        }
930	    }
931	
932	    /** Records in the audit what a payment just recorded holds on the client's account as credit, if anything. */
933	    private void recordCreditHeld(Payment payment) {
934	        BigDecimal credit = payment.credit();
935	        if (credit.signum() > 0) {
936	            audit.record("CREDIT_HELD payment=" + payment.getId() + " amount="
937	                    + credit.setScale(currencyOf(payment.getClientId()).scale(), RoundingMode.UNNECESSARY).toPlainString());
938	        }
939	    }
940	
941	    /** Records in the audit what a payment just recorded left written off on the invoice, if anything. */
942	    private void recordWriteOff(Invoice invoice) {
943	        BigDecimal writtenOff = invoice.writtenOff(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
944	        if (writtenOff.signum() > 0) {
945	            audit.record("INVOICE_WRITTEN_OFF id=" + invoice.getId() + " amount=" + writtenOff.toPlainString());
946	        }
947	    }
948	
949	    /**
950	     * Reverses the payment (a bounced cheque), undoing it on every invoice it was applied to, and
951	     * records it in the audit; empty if no such payment. A payment already reversed, or one that has
952	     * had any of its credit refunded, or credit from a credit note, is refused.
953	     */
954	    @Transactional
955	    public Optional<Payment> reversePayment(Long paymentId) {
956	        Optional<Payment> found = payments.findById(paymentId);
957	        found.ifPresent(payment -> {
958	            if (payment.isReversed()) {
959	                throw new InvoiceRejectedException("This payment has already been reversed.");
960	            }
961	            if (payment.getCreditNote() != null) {
962	                throw new InvoiceRejectedException("This is credit from a credit note, so it cannot be reversed.");
963	            }
964	            if (payment.getRefunded().signum() > 0) {
965	                throw new InvoiceRejectedException("This payment has had credit refunded, so it cannot be reversed.");
966	            }
967	            payment.reverse();
968	            payments.saveAndFlush(payment);
969	            // An invoice the payment settled early is no longer paid off, so its early discount lapses.
970	            payment.getAllocations().forEach(a -> invoices.findWithLinesById(a.getInvoiceId()).ifPresent(invoice -> {
971	                if (invoice.getEarlyDiscountTaken().signum() > 0) {
972	                    invoice.takeEarlyDiscount(BigDecimal.ZERO);
973	                    invoices.saveAndFlush(invoice);
974	                }
975	            }));
976	            audit.record("PAYMENT_REVERSED id=" + payment.getId() + " amount="
977	                    + payment.getAmount().setScale(currencyOf(payment.getClientId()).scale(), RoundingMode.UNNECESSARY)
978	                            .toPlainString());
979	        });
980	        return found;
981	    }
982	}
